export AWS_DEFAULT_REGION=eu-north-1 QAP_RUN=nug17-r QAP_BACKEND='aws:qap-coord-033593658551-eu-north-1?region=eu-north-1' QAP_BUCKET=qap-coord-033593658551-eu-north-1 QAP_ROLE=all
export QAP_RECIPE=nug17 QAP_NO_UB=0 QAP_REFERENCE=0 QAP_COMMIT=b1883fdd QAP_VISIBILITY=public QAP_GATES='none'
